import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
        m = int(next(iterator))
        q = int(next(iterator))
    except StopIteration:
        return

    T = [0] * (n + 1)
    for i in range(1, n + 1):
        T[i] = int(next(iterator))

    edges = []
    adj = defaultdict(list)

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        edges.append((w, u, v))
        adj[u].append((v, w))
        adj[v].append((u, w))

    queries = []
    for _ in range(q):
        x = int(next(iterator))
        y = int(next(iterator))
        k = int(next(iterator))
        queries.append((x, y, k))

    edges.sort(key=lambda x: x[0])

    parent = list(range(n + 1))
    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_j] = root_i
            return True
        return False

    ans = [-1] * q

    for idx, (x, y, k) in enumerate(queries):
        if x == y:
            unique_types = {T[x]}
            if len(unique_types) >= k:
                ans[idx] = 0
            continue

        if k > n:
            continue

        low = 0
        high = len(edges) - 1
        best_idx = -1

        temp_parent = list(range(n + 1))

        def get_components(limit_idx):
            comp_parent = list(range(n + 1))
            def gf(i):
                path = []
                while comp_parent[i] != i:
                    path.append(i)
                    i = comp_parent[i]
                for node in path:
                    comp_parent[node] = i
                return i
            def gu(i, j):
                ri = gf(i)
                rj = gf(j)
                if ri != rj:
                    comp_parent[rj] = ri
                    return True
                return False

            comps = {}
            for i in range(1, n + 1):
                root = gf(i)
                if root not in comps:
                    comps[root] = set()
                comps[root].add(T[i])

            return comps, gf, gu

        if low > high:
            pass
        else:
            while low <= high:
                mid = (low + high) // 2
                w_mid, u_mid, v_mid = edges[mid]

                comp_parent = list(range(n + 1))
                def gf_local(i):
                    path = []
                    while comp_parent[i] != i:
                        path.append(i)
                        i = comp_parent[i]
                    for node in path:
                        comp_parent[node] = i
                    return i

                def gu_local(i, j):
                    ri = gf_local(i)
                    rj = gf_local(j)
                    if ri != rj:
                        comp_parent[rj] = ri
                        return True
                    return False

                for i in range(mid + 1):
                    _, u, v = edges[i]
                    gu_local(u, v)

                root_x = gf_local(x)
                root_y = gf_local(y)

                if root_x == root_y:
                    types_set = set()
                    curr = x
                    visited = set()
                    stack = [curr]
                    visited.add(curr)
                    types_set.add(T[curr])

                    while stack:
                        node = stack.pop()
                        for neighbor, weight in adj[node]:
                            if neighbor not in visited:
                                root_n = gf_local(neighbor)
                                if root_n == root_x:
                                    visited.add(neighbor)
                                    types_set.add(T[neighbor])
                                    stack.append(neighbor)

                    if len(types_set) >= k:
                        best_idx = mid
                        high = mid - 1
                    else:
                        low = mid + 1
                else:
                    low = mid + 1

        if best_idx != -1:
            ans[idx] = edges[best_idx][0]

    for a in ans:
